namespace sv_71e47af25a4e4fae9eb5bde2715cbbc7.Services;

public class WarehouseState
{
    public string CurrentWarehouseId { get; private set; } = "WH-001";
    public string CurrentWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse == default || warehouse.Id == CurrentWarehouseId)
            return;

        CurrentWarehouseId = warehouse.Id;
        CurrentWarehouseName = warehouse.Name;
        OnChange?.Invoke();
    }
}

namespace sv_71e47af25a4e4fae9eb5bde2715cbbc7.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    public void UpdateAlertCount(int newCount)
    {
        CurrentLowStockCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

